#include "harness_start.bash"

# "make clean" removes every target "make check" generated, and is the
# thing to reach for when the results on disk can't be trusted.  The
# result of a test the Configfile no longer names was generated by
# "make check" just the same, but the per-test clean rules are written
# from the tests that are there now, so none of them names the old one
# -- and the old one is exactly the result that can't be trusted.

mkdir -p src test/t

cat >Configfile <<'EOF'
LANGUAGES += bash

BINARIES  += t
SOURCES   += t.bash
TESTSRC   += stays.bash
TESTSRC   += goes.bash
EOF

echo 'echo hello' > src/t.bash
echo 'exit 0' > test/t/stays.bash
echo 'exit 1' > test/t/goes.bash

$PTEST_BINARY $PCONFIGURE_ARGS
make $MAKE_ARGS check || true
test -e check/t/goes.bash

sed -i '/goes.bash/d' Configfile
$PTEST_BINARY $PCONFIGURE_ARGS

make $MAKE_ARGS clean
find check -type f 2>/dev/null > left || true
cat left
test ! -s left

make $MAKE_ARGS check

exit 0
